// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        // keep the domain wide but admissible: positive amounts the contract can be funded with
        amount = bound(amount, 1, 100 ether);

        // fund the contract so the withdrawal is admissible
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;

        // owner is the deployer (this test contract), which can receive ETH
        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: any successful withdraw(v>0) moves exactly v wei out of c
        assertTrue(!ok || address(c).balance == balanceBefore - amount);
    }
}
